{
    "certificateSubjectName": "Elastetic",
    "publisherName": "Elastetic",
    "rfc3161TimeStampServer": "http://time.certum.pl"
}

const fs = require('node:fs');
const path = require('node:path');
const { rebuildNativeDependencies } = require('./rebuild_native_dependencies');

const APP_ID = 'io.md2.desktop';
const PRODUCT_NAME = 'MDÂ²';
const EXECUTABLE_NAME = 'md2';
const COPYRIGHT = 'Copyright Â© 2026 Elastetic';
const DEFAULT_RFC3161_TIMESTAMP_SERVER = 'http://timestamp.digicert.com';
const SIGNING_SECRETS_PATH = path.join(__dirname, 'signing_secrets.json');

function loadSigningSecrets(secretsPath = SIGNING_SECRETS_PATH) {
    if (!fs.existsSync(secretsPath)) return {};

    return JSON.parse(fs.readFileSync(secretsPath, 'utf8'));
}

function createSigntoolOptions(secrets = loadSigningSecrets()) {
    const options = {
        rfc3161TimeStampServer: secrets.rfc3161TimeStampServer || DEFAULT_RFC3161_TIMESTAMP_SERVER,
        signingHashAlgorithms: ['sha256'],
    };

    if (secrets.certificateSubjectName) options.certificateSubjectName = secrets.certificateSubjectName;
    if (secrets.certificateSha1) options.certificateSha1 = secrets.certificateSha1;
    if (secrets.publisherName) options.publisherName = secrets.publisherName;

    return options;
}

function assertSigningIdentityIsConfigured(secrets) {
    if (secrets.certificateSubjectName || secrets.certificateSha1) return;

    throw new Error(
        `Missing signing identity: copy signing_secrets.example.json to ${SIGNING_SECRETS_PATH} and set `
        + 'certificateSubjectName (or certificateSha1) plus publisherName.',
    );
}

function createBuilderConfig(secrets = loadSigningSecrets()) {
    assertSigningIdentityIsConfigured(secrets);

    return {
        appId: APP_ID,
        asar: true,
        beforeBuild: rebuildNativeDependencies,
        copyright: COPYRIGHT,
        directories: {
            buildResources: 'build',
            output: path.join('..', 'release'),
        },
        extraResources: [{ from: '.env', to: '.env' }],
        extraMetadata: { main: 'desktop/main.js' },
        files: [
            '!**/*.map',
            {
                from: '.',
                to: '.',
                filter: ['package.json'],
            },
            {
                from: '.',
                to: 'desktop',
                filter: [
                    'main.js',
                    'src/**/*.js',
                    'src/**/*.mjs',
                    'build/md2.ico',
                    '!**/*.test.mjs',
                ],
            },
            {
                from: '../app/dist',
                to: 'desktop/renderer',
                filter: ['**/*', '!**/*.map'],
            },
            {
                from: '../shared',
                to: 'shared',
                filter: ['**/*'],
            },
        ],
        forceCodeSigning: true,
        productName: PRODUCT_NAME,
        win: {
            artifactName: 'MD2-Setup-${version}-${arch}.${ext}',
            executableName: EXECUTABLE_NAME,
            icon: 'build/md2.ico',
            signtoolOptions: createSigntoolOptions(secrets),
            target: [{ arch: ['x64'], target: 'nsis' }],
        },
        nsis: {
            artifactName: 'MD2-Setup-${version}-${arch}.${ext}',
            installerIcon: 'build/md2.ico',
            uninstallerIcon: 'build/md2.ico',
        },
    };
}

module.exports = {
    APP_ID,
    COPYRIGHT,
    DEFAULT_RFC3161_TIMESTAMP_SERVER,
    EXECUTABLE_NAME,
    PRODUCT_NAME,
    SIGNING_SECRETS_PATH,
    createBuilderConfig,
    createSigntoolOptions,
    loadSigningSecrets,
};

import { mkdtempSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

const require = createRequire(import.meta.url);
const {
    APP_ID,
    DEFAULT_RFC3161_TIMESTAMP_SERVER,
    EXECUTABLE_NAME,
    PRODUCT_NAME,
    SIGNING_SECRETS_PATH,
    createBuilderConfig,
    createSigntoolOptions,
    loadSigningSecrets,
} = require('./builder_config');

describe('electron-builder configuration', () => {
    it('defines signed Windows x64 NSIS metadata and bundled runtime inputs', () => {
        const config = createBuilderConfig({ certificateSubjectName: 'Example Certificate' });

        expect(config).toMatchObject({
            appId: APP_ID,
            asar: true,
            beforeBuild: expect.any(Function),
            extraMetadata: { main: 'desktop/main.js' },
            forceCodeSigning: true,
            productName: PRODUCT_NAME,
            win: {
                executableName: EXECUTABLE_NAME,
                icon: 'build/md2.ico',
                target: [{ arch: ['x64'], target: 'nsis' }],
            },
        });
        expect(config.files).toContain('!**/*.map');
        expect(config.files).toContainEqual(expect.objectContaining({ from: '.', to: 'desktop' }));
        expect(config.files).toContainEqual(expect.objectContaining({ from: '../app/dist', to: 'desktop/renderer' }));
        expect(config.files).toContainEqual(expect.objectContaining({ from: '../shared', to: 'shared' }));
        expect(config.extraResources).toEqual([{ from: '.env', to: '.env' }]);
    });

    it('selects a certificate-store identity only when configured', () => {
        expect(createSigntoolOptions({})).not.toHaveProperty('certificateSubjectName');
        expect(createSigntoolOptions({
            certificateSha1: 'ABC123',
            certificateSubjectName: 'Example Certificate',
            publisherName: 'Example Publisher',
        })).toMatchObject({
            certificateSha1: 'ABC123',
            certificateSubjectName: 'Example Certificate',
            publisherName: 'Example Publisher',
            signingHashAlgorithms: ['sha256'],
        });
    });

    it('uses the default timestamp server unless an override is configured', () => {
        expect(createSigntoolOptions({})).toMatchObject({ rfc3161TimeStampServer: DEFAULT_RFC3161_TIMESTAMP_SERVER });
        expect(createSigntoolOptions({ rfc3161TimeStampServer: 'http://time.certum.pl' }))
            .toMatchObject({ rfc3161TimeStampServer: 'http://time.certum.pl' });
    });

    it('refuses to build without a signing identity instead of producing an unsigned app', () => {
        expect(() => createBuilderConfig({ publisherName: 'Example Publisher' })).toThrow('Missing signing identity');
        expect(() => createBuilderConfig({ certificateSha1: 'ABC123' })).not.toThrow();
    });

    it('reads signing secrets from an uncommitted json file and tolerates its absence', () => {
        const directory = mkdtempSync(path.join(tmpdir(), 'md2-signing-'));
        const secretsPath = path.join(directory, 'signing_secrets.json');
        writeFileSync(secretsPath, JSON.stringify({ publisherName: 'Example Publisher' }));

        expect(loadSigningSecrets(secretsPath)).toEqual({ publisherName: 'Example Publisher' });
        expect(loadSigningSecrets(path.join(directory, 'missing.json'))).toEqual({});
        expect(SIGNING_SECRETS_PATH.endsWith(path.join('packaging', 'signing_secrets.json'))).toBe(true);
    });
});

