param(
    [Parameter(Mandatory = $true)]
    [string[]] $ArtifactPath,

    [Parameter(Mandatory = $true)]
    [string] $ExpectedPublisher
)

$ErrorActionPreference = 'Stop'

foreach ($path in $ArtifactPath) {
    $signature = Get-AuthenticodeSignature -LiteralPath $path
    if ($signature.Status -ne 'Valid') {
        throw "Invalid Authenticode signature for $path`: $($signature.Status)"
    }
    if ($signature.SignerCertificate.Subject.IndexOf($ExpectedPublisher, [System.StringComparison]::OrdinalIgnoreCase) -lt 0) {
        throw "Unexpected Authenticode publisher for $path`: $($signature.SignerCertificate.Subject)"
    }
    if ($null -eq $signature.TimeStamperCertificate) {
        throw "Missing Authenticode timestamp for $path"
    }
}

const { spawn } = require('node:child_process');
const path = require('node:path');

const repositoryRoot = path.resolve(__dirname, '..', '..');

function runNpm(args, spawnImplementation = spawn) {
    return new Promise((resolve, reject) => {
        const child = spawnImplementation('npm', args, {
            cwd: repositoryRoot,
            env: process.env,
            shell: process.platform === 'win32',
            stdio: 'inherit',
        });

        child.once('error', reject);
        child.once('exit', (code, signal) => {
            if (signal) {
                reject(new Error(`npm ${args.join(' ')} stopped by signal ${signal}`));
                return;
            }
            if (code !== 0) {
                reject(new Error(`npm ${args.join(' ')} failed with exit code ${code}`));
                return;
            }

            resolve();
        });
    });
}

async function buildWindows(runNpmImplementation = runNpm) {
    await runNpmImplementation(['run', 'build', '--prefix', 'app']);
    await runNpmImplementation(['run', 'package:windows', '--prefix', 'desktop']);
}

if (require.main === module) {
    buildWindows().catch((error) => {
        console.error(error.message);
        process.exitCode = 1;
    });
}

module.exports = { buildWindows, runNpm };

import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { assertAppContentIsReleaseSafe, assertPackageEntries, resolveArtifactPaths } from './verify_windows_package.mjs';

const validEntries = [
    'package.json',
    'desktop/main.js',
    'desktop/src/actions/agent/claude_usage_terminal_worker.js',
    'desktop/src/shell/preload.js',
    'desktop/renderer/index.html',
    'desktop/renderer/assets/index.js',
    'desktop/src/shell/renderer_security.js',
    'shared/action_definitions.mjs',
    'node_modules/@aptabase/electron/package.json',
    'node_modules/@sentry/electron/package.json',
    'node_modules/electron-store/package.json',
    'node_modules/electron-window-state/package.json',
    'node_modules/ssh2/package.json',
    'node_modules/ws/package.json',
];

describe('Windows package verification', () => {
    it('uses predictable versioned x64 artifact paths', () => {
        expect(resolveArtifactPaths('2.3.4', 'C:\\release')).toEqual({
            asarPath: path.join('C:\\release', 'MD2-2.3.4-win-x64-unpacked', 'resources', 'app.asar'),
            environmentPath: path.join('C:\\release', 'MD2-2.3.4-win-x64-unpacked', 'resources', '.env'),
            executablePath: path.join('C:\\release', 'MD2-2.3.4-win-x64-unpacked', 'md2.exe'),
            installerPath: path.join('C:\\release', 'MD2-Setup-2.3.4-x64.exe'),
            sourceUnpackedDirectory: path.join('C:\\release', 'win-unpacked'),
            unpackedDirectory: path.join('C:\\release', 'MD2-2.3.4-win-x64-unpacked'),
        });
    });

    it('accepts required runtime and renderer files', () => {
        expect(assertPackageEntries(validEntries)).toEqual(validEntries);
    });

    it('rejects missing renderer assets and certificate material', () => {
        expect(() => assertPackageEntries(validEntries.filter((entry) => !entry.startsWith('desktop/renderer/assets/'))))
            .toThrow('Packaged application missing renderer assets');
        expect(() => assertPackageEntries([...validEntries, 'build/signing.pfx']))
            .toThrow('Forbidden packaged files: build/signing.pfx');
        expect(() => assertPackageEntries([...validEntries, 'desktop/packaging/signing_secrets.json']))
            .toThrow('Forbidden packaged files: desktop/packaging/signing_secrets.json');
    });

    it('rejects development URLs and signing-password names in app content', () => {
        const mainEntry = path.join('desktop', 'main.js');
        const extractFile = (_asarPath, entry) => Buffer.from(entry === mainEntry ? 'http://localhost:5173' : 'release');

        expect(() => assertAppContentIsReleaseSafe('app.asar', validEntries, extractFile))
            .toThrow('Forbidden release content in desktop/main.js: http://localhost:5173');
    });
});

import { extractFile, listPackage } from '@electron/asar';
import { execFile } from 'node:child_process';
import { existsSync } from 'node:fs';
import { rename } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import packageJson from '../package.json' with { type: 'json' };

const { loadSigningSecrets } = createRequire(import.meta.url)('./builder_config');
const execFileAsync = promisify(execFile);
const currentDirectory = path.dirname(fileURLToPath(import.meta.url));
const releaseRoot = path.resolve(currentDirectory, '..', '..', 'release');
const REQUIRED_ASAR_ENTRIES = [
    'package.json',
    'desktop/main.js',
    'desktop/src/actions/agent/claude_usage_terminal_worker.js',
    'desktop/src/shell/preload.js',
    'desktop/renderer/index.html',
    'desktop/src/shell/renderer_security.js',
    'shared/action_definitions.mjs',
    'node_modules/@aptabase/electron/package.json',
    'node_modules/@sentry/electron/package.json',
    'node_modules/electron-store/package.json',
    'node_modules/electron-window-state/package.json',
    'node_modules/ssh2/package.json',
    'node_modules/ws/package.json',
];
const FORBIDDEN_ENTRY_PATTERN = /(?:(?:^|\/).+\.(?:key|map|p12|pem|pfx)|(?:^|\/)signing_secrets\.json)$/iu;
const FORBIDDEN_APP_CONTENT = ['http://localhost:5173', 'certificateSha1'];
const APP_OWNED_ENTRY_PATTERN = /^(?:desktop|shared)\/.+\.(?:css|html|js|json|mjs|svg|txt)$/u;

function normalizeAsarEntry(entry) {
    return entry.replace(/^[/\\]+/u, '').replaceAll('\\', '/');
}

export function resolveArtifactPaths(version, outputDirectory = releaseRoot) {
    const unpackedDirectoryName = `MD2-${version}-win-x64-unpacked`;
    const unpackedDirectory = path.join(outputDirectory, unpackedDirectoryName);

    return {
        asarPath: path.join(unpackedDirectory, 'resources', 'app.asar'),
        environmentPath: path.join(unpackedDirectory, 'resources', '.env'),
        executablePath: path.join(unpackedDirectory, 'md2.exe'),
        installerPath: path.join(outputDirectory, `MD2-Setup-${version}-x64.exe`),
        sourceUnpackedDirectory: path.join(outputDirectory, 'win-unpacked'),
        unpackedDirectory,
    };
}

export function assertPackageEntries(entries) {
    const normalizedEntries = entries.map(normalizeAsarEntry);
    const missingEntries = REQUIRED_ASAR_ENTRIES.filter((entry) => !normalizedEntries.includes(entry));
    if (missingEntries.length > 0) throw new Error(`Packaged application missing: ${missingEntries.join(', ')}`);

    if (!normalizedEntries.some((entry) => entry.startsWith('desktop/renderer/assets/'))) {
        throw new Error('Packaged application missing renderer assets');
    }

    const forbiddenEntries = normalizedEntries.filter((entry) => FORBIDDEN_ENTRY_PATTERN.test(entry));
    if (forbiddenEntries.length > 0) throw new Error(`Forbidden packaged files: ${forbiddenEntries.join(', ')}`);

    return normalizedEntries;
}

export function assertAppContentIsReleaseSafe(asarPath, entries, extractFileImplementation = extractFile) {
    const appEntries = entries.filter((entry) => APP_OWNED_ENTRY_PATTERN.test(entry));

    for (const entry of appEntries) {
        const archiveEntry = entry.replaceAll('/', path.sep);
        const content = extractFileImplementation(asarPath, archiveEntry);
        const forbiddenValue = FORBIDDEN_APP_CONTENT.find((value) => content.includes(Buffer.from(value)));
        if (forbiddenValue) throw new Error(`Forbidden release content in ${entry}: ${forbiddenValue}`);
    }
}

async function finalizeUnpackedDirectory(paths) {
    const { sourceUnpackedDirectory, unpackedDirectory } = paths;
    if (!existsSync(sourceUnpackedDirectory)) {
        if (existsSync(unpackedDirectory)) return;

        throw new Error(`Missing unpacked application: ${sourceUnpackedDirectory}`);
    }
    if (existsSync(unpackedDirectory)) throw new Error(`Unpacked artifact already exists: ${unpackedDirectory}`);

    await rename(sourceUnpackedDirectory, unpackedDirectory);
}

async function verifySignatures(paths, expectedPublisher) {
    if (!expectedPublisher) throw new Error('publisherName in signing_secrets.json is required to verify signed artifacts');

    const scriptPath = path.join(currentDirectory, 'verify_authenticode.ps1');
    for (const artifactPath of [paths.executablePath, paths.installerPath]) {
        const args = [
            '-NoProfile',
            '-ExecutionPolicy',
            'Bypass',
            '-File',
            scriptPath,
            '-ArtifactPath',
            artifactPath,
            '-ExpectedPublisher',
            expectedPublisher,
        ];
        await execFileAsync('powershell.exe', args);
    }
}

export async function verifyWindowsPackage(secrets = loadSigningSecrets()) {
    const paths = resolveArtifactPaths(packageJson.version);
    await finalizeUnpackedDirectory(paths);

    for (const artifactPath of [paths.asarPath, paths.environmentPath, paths.executablePath, paths.installerPath]) {
        if (!existsSync(artifactPath)) throw new Error(`Missing release artifact: ${artifactPath}`);
    }

    const entries = assertPackageEntries(listPackage(paths.asarPath));
    assertAppContentIsReleaseSafe(paths.asarPath, entries);
    await verifySignatures(paths, secrets.publisherName);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    verifyWindowsPackage().catch((error) => {
        console.error(error.message);
        process.exitCode = 1;
    });
}

import { existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { describe, expect, it, vi } from 'vitest';

const require = createRequire(import.meta.url);
const { buildWindows } = require('./build_windows');

const repositoryRoot = path.resolve(import.meta.dirname, '..', '..');

describe('Windows release build', () => {
    it('builds React before packaging Electron', async () => {
        const runNpm = vi.fn(async () => undefined);

        await buildWindows(runNpm);

        expect(runNpm.mock.calls).toEqual([
            [['run', 'build', '--prefix', 'app']],
            [['run', 'package:windows', '--prefix', 'desktop']],
        ]);
    });

    it('does not package when the React build fails', async () => {
        const error = new Error('React build failed');
        const runNpm = vi.fn(async () => { throw error; });

        await expect(buildWindows(runNpm)).rejects.toBe(error);
        expect(runNpm).toHaveBeenCalledTimes(1);
    });

    it('is reachable through the repository build:windows script', () => {
        const rootManifest = require(path.join(repositoryRoot, 'package.json'));
        const [command, scriptPath] = rootManifest.scripts['build:windows'].split(' ');

        expect(command).toBe('node');
        expect(existsSync(path.join(repositoryRoot, scriptPath))).toBe(true);
    });
});

